describe('Bottom Sheet Dropdown Replacement on Mobile', () => {
  beforeEach(() => {
    cy.visit('/dropdown-page');
  });

  it('should display bottom sheet when mobile view is detected and replace dropdown with bottom sheet', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Verify dropdown is visible
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify dropdown content is present
    cy.get('[data-testid="dropdown-item"]').should('have.length.greaterThan', 0);

    // Verify dropdown has a close button
    cy.get('[data-testid="dropdown-close-btn"]').should('be.visible');

    // Verify bottom sheet container is hidden
    cy.get('[data-testid="bottom-sheet-container"]').should('not.exist');

    // Intercept API call to fetch dropdown data
    cy.intercept('GET', '/api/dropdown-data').as('fetchDropdownData');

    // Trigger dropdown open
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Wait for API call
    cy.wait('@fetchDropdownData');

    // Verify bottom sheet container is now visible
    cy.get('[data-testid="bottom-sheet-container"]').should('be.visible');

    // Verify bottom sheet has correct content
    cy.get('[data-testid="bottom-sheet-content"]').should('contain', 'Dropdown items');

    // Verify dropdown is hidden
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');

    // Verify close button is visible
    cy.get('[data-testid="dropdown-close-btn"]').should('be.visible');

    // Verify bottom sheet has close button
    cy.get('[data-testid="bottom-sheet-close-btn"]').should('be.visible');

    // Verify bottom sheet is positioned correctly
    cy.get('[data-testid="bottom-sheet-container"]').should('have.css', 'bottom', '0');

    // Verify bottom sheet is scrollable
    cy.get('[data-testid="bottom-sheet-content"]').should('be.scrollable');

    // Verify dropdown menu is hidden when bottom sheet is open
    cy.get('[data-testid="dropdown-menu"]').should('not.exist');
  });

  it('should close bottom sheet when close button is clicked on mobile', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Open bottom sheet
    cy.get('[data-testid="dropdown-trigger"]').click();

    // Wait for API call
    cy.wait('@fetchDropdownData');

    // Verify bottom sheet is open
    cy.get('[data-testid="bottom-sheet-container"]').should('be.visible');

    // Verify close button is visible
    cy.get('[data-testid="bottom-sheet-close-btn"]').should('be.visible');

    // Click close button
    cy.get('[data-testid="bottom-sheet-close-btn"]').click();

    // Verify bottom sheet is closed
    cy.get('[data-testid="bottom-sheet-container"]').should('not.exist');

    // Verify dropdown menu is visible again
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');

    // Verify dropdown content is restored
    cy.get('[data-testid="dropdown-item"]').should('have.length.greaterThan', 0);

    // Verify dropdown close button is visible
    cy.get('[data-testid="dropdown-close-btn"]').should('be.visible');
  });
});
